--
-- Table structure for table `task_points`
--

CREATE TABLE `task_points` (
  `id` mediumint(7) NOT NULL COMMENT 'Unique identifier',
  `show_id` tinyint(2) UNSIGNED DEFAULT NULL COMMENT 'Show ID',
  `season_id` smallint(3) UNSIGNED DEFAULT NULL COMMENT 'Season ID',
  `episode_id` smallint(4) UNSIGNED DEFAULT NULL COMMENT 'Episode ID',
  `task_id` smallint(5) UNSIGNED DEFAULT NULL COMMENT 'Task ID',
  `attempt_id` mediumint(6) UNSIGNED DEFAULT NULL COMMENT 'Attempt ID',
  `contestant_id` smallint(4) UNSIGNED DEFAULT NULL COMMENT 'Contestant ID',
  `base_points` decimal(4,2) DEFAULT NULL COMMENT 'Base points awarded',
  `adjustment_points` decimal(4,2) DEFAULT NULL COMMENT 'Adjustment points',
  `total_points` decimal(4,2) DEFAULT NULL COMMENT 'Total points, if adjustment points are applied',
  `disqualification` tinyint(1) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Binary indicator of whether this was a disqualification.',
  `out_of_competition` tinyint(1) UNSIGNED NOT NULL DEFAULT '0' COMMENT 'Was the task out of competition?'
) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci;

